import Foundation
import CoreImage
import CoreImage.CIFilterBuiltins
import ImageIO
import UniformTypeIdentifiers

/// SF-0802/0806/1206: generated bytes enter the same immutable resource
/// pipeline as imported images. No network encoder, tracking URL or bitmap mock.
actor QRCodeResourceWorker {
    enum Failure: Error, LocalizedError {
        case invalidPayload, unavailableEncoder, invalidOutput
        var errorDescription: String? {
            switch self {
            case .invalidPayload: "Enter a complete HTTP or HTTPS URL of at most 1,024 UTF-8 bytes without credentials."
            case .unavailableEncoder: "The local QR encoder is unavailable. The Footer is unchanged."
            case .invalidOutput: "The generated QR could not be decoded reliably. Try a shorter destination URL."
            }
        }
    }
    static let namespace = CanonicalQRCode.namespace
    static func validURL(_ payload: String) -> Bool {
        payload.utf8.count <= 1_024 && CanonicalLinkTarget.validateExternal(payload)
    }
    func prepare(payload: String) throws -> PreparedImageImport {
        guard Self.validURL(payload) else { throw Failure.invalidPayload }
        try Task.checkCancellation()
        let filter = CIFilter.qrCodeGenerator()
        filter.message = Data(payload.utf8); filter.correctionLevel = "M"
        let context = CIContext(options: [.cacheIntermediates: false])
        guard let output = filter.outputImage,
              let qr = context.createCGImage(output, from: output.extent),
              qr.width == qr.height else { throw Failure.unavailableEncoder }
        // Four clear modules on every edge; an integer raster scale avoids
        // antialiasing the code into an undecodable decorative pattern.
        let moduleScale = 8, quietModules = 4
        let pixels = (qr.width + quietModules * 2) * moduleScale
        guard pixels <= ImageAsset.maximumPixelDimension,
              let bitmap = CGContext(data: nil, width: pixels, height: pixels, bitsPerComponent: 8,
                  bytesPerRow: pixels * 4, space: CGColorSpace(name: CGColorSpace.sRGB)!,
                  bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) else { throw Failure.invalidOutput }
        bitmap.setFillColor(CGColor(gray: 1, alpha: 1));bitmap.fill(CGRect(x: 0, y: 0, width: pixels, height: pixels))
        bitmap.interpolationQuality = .none
        bitmap.draw(qr, in: CGRect(x: quietModules * moduleScale, y: quietModules * moduleScale,
            width: qr.width * moduleScale, height: qr.height * moduleScale))
        let data = NSMutableData()
        guard let image = bitmap.makeImage(),
              let destination = CGImageDestinationCreateWithData(data, UTType.png.identifier as CFString, 1, nil)
        else { throw Failure.invalidOutput }
        CGImageDestinationAddImage(destination, image, nil)
        guard CGImageDestinationFinalize(destination), data.length <= ProjectResourceIndex.maximumResourceBytes
        else { throw Failure.invalidOutput }
        try Task.checkCancellation()
        let bytes = data as Data
        try Self.verify(bytes, payload: payload)
        let digest = ProjectResourceStore.digest(bytes), id = ResourceID()
        let descriptor = ProjectResourceDescriptor(id: id, filename: "QR Code.png", mediaType: ImageAssetFormat.png.mediaType,
            byteCount: bytes.count, sha256: digest)
        return .init(asset: .init(resourceID: id, displayName: "QR Code", originalFilename: "QR Code.png", format: .png,
            pixelWidth: pixels, pixelHeight: pixels, byteCount: bytes.count, contentHash: digest), descriptor: descriptor, data: bytes)
    }
    static func verify(_ bytes: Data, payload: String) throws {
        try ProjectQRCodeVerifier.verify(bytes, payload: payload)
    }

}

import Foundation

enum FooterGroupPreset: String, CaseIterable, Sendable { case about, contact, empty, qr }
struct PreparedFooterGroup: Sendable {
    let command: DocumentCommand
    let groupID: NodeID
    let columnsID: NodeID
    let resource: PreparedImageImport?
}

/// SF-0304-002/005, SF-0502-002/003/005: convenience compiles ordinary
/// containers/content into one existing command batch, without new roles.
enum FooterContentCommandRegistry {
    static func prepare(preset: FooterGroupPreset, footerID: NodeID, selectedGridID: NodeID?,
                        createColumnsConfirmed: Bool, document: CanonicalDocument, pageID: PageID,
                        qr: PreparedImageImport? = nil, qrPayload: String? = nil) throws -> PreparedFooterGroup {
        guard let page = document.pages.first(where: { $0.id == pageID }),
              let footer = page.nodes.first(where: { $0.id == footerID }), CanonicalPageFlow.role(footer) == .footer,
              !footer.selectionBooleanProperty("locked"), !footer.selectionBooleanProperty("hidden"),
              let contentID = CanonicalPageChrome.reference(CanonicalPageChrome.contentKey, on: footer),
              let content = page.nodes.first(where: { $0.id == contentID }), content.kind == .stack
        else { throw DesignInspectorError.unavailable("Select an editable Footer with its original content container. Restore missing content with Undo.") }
        let byID = Dictionary(uniqueKeysWithValues: page.nodes.map { ($0.id, $0) })
        func belongs(_ id: NodeID, under ancestor: NodeID) -> Bool {
            var current = id, visited = Set<NodeID>()
            while visited.insert(current).inserted, let node = byID[current] {
                if current == ancestor { return true }
                guard case .node(let parent) = node.parent else { return false }
                current = parent
            }
            return false
        }
        func requireEditable(_ id: NodeID) throws {
            var current: NodeID? = id, seen = Set<NodeID>()
            while let id = current, let node = byID[id] {
                guard seen.insert(id).inserted, !node.selectionBooleanProperty("locked"), !node.selectionBooleanProperty("hidden")
                else { throw DesignInspectorError.unavailable("Unlock and show the Footer and its containing layout before adding content.") }
                if case .node(let parent) = node.parent { current = parent } else { current = nil }
            }
        }
        try requireEditable(content.id)
        var commands: [DocumentCommand] = []
        func set(_ node: DocumentNode, _ key: String, _ value: PropertyValue) {
            let old = node.insertionProperty(key)
            guard old?.value != value || old?.origin != .authored else { return }
            commands.append(.setProperty(.init(pageID: pageID, nodeID: node.id,
                property: .init(id: old?.id ?? PropertyID(), key: .init(rawValue: key), value: value, origin: .authored))))
        }
        func property(_ key: String, _ value: PropertyValue) -> NodeProperty { .init(key: .init(rawValue: key), value: value, origin: .authored) }
        func geometry(width: Double = 280, height: Double = 32) -> [NodeProperty] {
            [property("layout.x", .number(0)), property("layout.y", .number(0)),
             property("layout.width", .number(width)), property("layout.height", .number(height)),
             property(CanonicalSizingConstraints.prefix + "widthMode", .string("fill"))]
        }
        func container(kind: NodeKind = .stack, name: String, parent: NodeID, axis: String = "vertical", gap: Double = 12) -> DocumentNode {
            .init(kind: kind, name: name, parent: .node(parent), properties: geometry(height: 120) + [
                property("layout.container.kind", .string(kind == .grid ? "grid" : "stack")),
                property("layout.axis", .string(axis)), property("layout.gap", .number(gap)), property("layout.padding", .number(0)),
                property("layout.align", .string("start")), property(CanonicalSizingConstraints.prefix + "heightMode", .string("hug")),
                property(CanonicalFillLayerCodec.orderKey, .string("")), property("style.border", .string("none"))])
        }
        let grid: DocumentNode
        let existing = content.childIDs.compactMap { byID[$0] }.filter { $0.kind == .grid }
        if let selectedGridID {
            guard let selected = byID[selectedGridID], selected.kind == .grid, belongs(selectedGridID, under: content.id)
            else { throw DesignInspectorError.stale }
            grid = selected
        } else if existing.count == 1 { grid = existing[0] }
        else {
            guard existing.isEmpty else { throw DesignInspectorError.unavailable("Select the Footer grid that should receive this group.") }
            guard createColumnsConfirmed else { throw DesignInspectorError.unavailable("Create responsive Footer columns before adding this group.") }
            let managed = [CanonicalPageChrome.titleKey, CanonicalPageChrome.navigationKey]
                .compactMap { CanonicalPageChrome.reference($0, on: footer) }.compactMap { byID[$0] }
                .filter { $0.parent == .node(content.id) }
            if !managed.isEmpty {
                var row = container(name: "Footer heading and navigation", parent: content.id, axis: "horizontal", gap: 24)
                row.properties.append(property(ResponsiveContainerLayoutResolver.key(.axis, breakpoint: .mobile), .string("vertical")))
                commands.append(.insertNode(.init(pageID: pageID, node: row, index: 0)))
                for (index, child) in managed.enumerated() {
                    commands.append(.moveNode(.init(pageID: pageID, nodeID: child.id, destination: .node(row.id), index: index)))
                    let isTitle = CanonicalPageChrome.reference(CanonicalPageChrome.titleKey, on: footer) == child.id
                    if !isTitle { set(child, CanonicalSizingConstraints.prefix + "widthMode", .string("fill")) }
                }
            }
            var columns = container(kind: .grid, name: "Footer columns", parent: content.id, gap: 24)
            columns.properties += [property("layout.grid.columns", .number(3)), property("layout.grid.placement", .string("row-major")),
                property(ResponsiveContainerLayoutResolver.key(.columns, breakpoint: .tablet), .number(2)),
                property(ResponsiveContainerLayoutResolver.key(.columns, breakpoint: .mobile), .number(1))]
            let index = content.childIDs.count + (managed.isEmpty ? 0 : 1 - managed.count)
            commands.append(.insertNode(.init(pageID: pageID, node: columns, index: index)))
            grid = columns
            set(footer, CanonicalPageChrome.arrangementKey, .string("custom"))
            set(footer, CanonicalSizingConstraints.prefix + "heightMode", .string("hug"))
            set(content, CanonicalSizingConstraints.prefix + "widthMode", .string("fill"))
            set(content, "layout.axis", .string("vertical"));set(content, "layout.gap", .number(28))
            set(content, CanonicalSizingConstraints.prefix + "heightMode", .string("hug"))
        }
        if byID[grid.id] != nil { try requireEditable(grid.id) }
        let name: String = switch preset {case .about: "About Us";case .contact: "Contact Us";case .empty: "New section";case .qr: "Scan to explore"}
        let group = container(name: name, parent: grid.id)
        commands.append(.insertNode(.init(pageID: pageID, node: group, index: grid.childIDs.count)))
        var children: [DocumentNode] = []
        func text(_ value: String, heading: Bool = false) -> DocumentNode {
            .init(kind: .text, name: heading ? name : "Contact detail", parent: .node(group.id),
                properties: geometry(height: heading ? 28 : 24) + [property("content.text", .string(value)),
                    property(CanonicalSizingConstraints.prefix + "heightMode", .string("hug")),
                    property(CanonicalTypography.namespace + "size", .number(heading ? 20 : 16)),
                    property(CanonicalTypography.namespace + "lineHeight", .number(heading ? 28 : 24))]
                    + (heading ? [property(CanonicalSemanticElement.key, .string("h3"))] : []))
        }
        func link(label: String, target: CanonicalLinkTarget) -> DocumentNode {
            .init(kind: .link, name: label, parent: .node(group.id), properties: geometry() + [
                property(CanonicalLinkTarget.labelKey, .string(label)),
                property(CanonicalSizingConstraints.prefix + "heightMode", .string("hug"))]
                + target.properties.map { property($0.0, $0.1) })
        }
        children.append(text(name, heading: true))
        var resource: PreparedImageImport?
        switch preset {
        case .about:
            for destination in document.websitePages.filter({ $0.role != .notFound }).prefix(3) {
                children.append(link(label: destination.name, target: .page(destination.id)))
            }
        case .contact:
            children += [text("Add your contact details"), link(label: "Example website", target: .external("https://example.com"))]
        case .empty: break
        case .qr:
            guard let qr, let qrPayload, QRCodeResourceWorker.validURL(qrPayload) else { throw DesignInspectorError.unavailable("Enter a valid QR destination URL.") }
            let existing = document.imageAssets.first { $0.contentHash == qr.asset.contentHash }
            let asset = existing ?? qr.asset
            if existing == nil { commands.append(.insertImageAsset(.init(asset: asset, index: document.imageAssets.count)));resource = qr }
            let pixels = Double(min(320, asset.pixelWidth))
            var image = DocumentNode(kind: .image, name: "QR Code", parent: .node(group.id), properties: geometry(width: pixels, height: pixels))
            image.properties += [property(CanonicalSizingConstraints.prefix + "maxWidth", .number(pixels)),
                property(CanonicalImageStyle.namespace + "assetID", .string(asset.id.description)),
                property(CanonicalImageStyle.namespace + "fit", .string("fit")),
                property(CanonicalImageStyle.namespace + "focal.x", .number(0.5)), property(CanonicalImageStyle.namespace + "focal.y", .number(0.5)),
                property(CanonicalImageStyle.namespace + "decorative", .boolean(false)),
                property(CanonicalImageStyle.namespace + "alt", .string("QR code for " + qrPayload)),
                property(CanonicalQRCode.namespace + "payload", .string(qrPayload)),
                property(CanonicalQRCode.namespace + "hash", .string(asset.contentHash))]
            children += [image, link(label: "Open example destination", target: .external(qrPayload))]
        }
        for (index, child) in children.enumerated() { commands.append(.insertNode(.init(pageID: pageID, node: child, index: index))) }
        let command = DocumentCommand.batch(commands)
        let availability = CommandRegistry().availability(for: command, in: document)
        guard availability.isEnabled else { throw DesignInspectorError.unavailable(availability.disabledReason ?? "This Footer cannot accept the new content.") }
        return .init(command: command, groupID: group.id, columnsID: grid.id, resource: resource)
    }
}

actor FooterContentWorker {
    private let encoder = QRCodeResourceWorker()
    func prepare(preset: FooterGroupPreset, footerID: NodeID, selectedGridID: NodeID?,
                 createColumnsConfirmed: Bool, document: CanonicalDocument, pageID: PageID,
                 payload: String) async throws -> PreparedFooterGroup {
        let qr = preset == .qr ? try await encoder.prepare(payload: payload) : nil
        try Task.checkCancellation()
        let result = try FooterContentCommandRegistry.prepare(preset: preset, footerID: footerID,
            selectedGridID: selectedGridID, createColumnsConfirmed: createColumnsConfirmed,
            document: document, pageID: pageID, qr: qr, qrPayload: payload)
        var draft = document
        _ = try CommandRegistry().apply(result.command, to: &draft)
        try draft.validate()
        return result
    }
}

import SwiftUI

struct FooterContentControls: View {
    @ObservedObject var state: WorkspaceShellState
    let footer: DocumentNode
    @State private var presenting = false
    @State private var preset = FooterGroupPreset.about
    @State private var payload = "https://example.com"
    private var page: DocumentPage? { state.documentSession.document.pages.first { $0.id == state.effectiveSelectedPageID } }
    private var content: DocumentNode? {
        guard let id = CanonicalPageChrome.reference(CanonicalPageChrome.contentKey, on: footer) else { return nil }
        return page?.nodes.first { $0.id == id }
    }
    private var grids: [DocumentNode] { page?.nodes.filter { content?.childIDs.contains($0.id) == true && $0.kind == .grid } ?? [] }
    @State private var selectedGrid: NodeID?
    var body: some View {
        Button("Add Footer Section…") { presenting = true }
            .disabled(state.isAddingFooterContent || content == nil)
            .accessibilityIdentifier("inspector.footer.addGroup")
            .sheet(isPresented: $presenting) {
                VStack(alignment: .leading, spacing: 16) {
                    Text("Add Footer Section").font(.title2)
                    Text("Headings, links, text and images remain ordinary editable elements. Use Layout to change their spacing and responsive sizes.")
                        .fixedSize(horizontal: false, vertical: true)
                    Picker("Starting content", selection: $preset) {
                        Text("About Us and page links").tag(FooterGroupPreset.about)
                        Text("Contact Us and details").tag(FooterGroupPreset.contact)
                        Text("QR code and destination link").tag(FooterGroupPreset.qr)
                        Text("Empty section with heading").tag(FooterGroupPreset.empty)
                    }.accessibilityIdentifier("footer.group.preset")
                    if grids.count > 1 {
                        Picker("Footer columns", selection: $selectedGrid) {
                            Text("Choose columns").tag(Optional<NodeID>.none)
                            ForEach(grids) { Text($0.name).tag(Optional($0.id)) }
                        }.accessibilityIdentifier("footer.group.destination")
                    }
                    if grids.isEmpty {
                        Text("Adding this section creates responsive columns and moves the existing title/navigation into a heading row. All content is preserved in one undoable change.")
                            .font(.callout).fixedSize(horizontal: false, vertical: true)
                    }
                    if preset == .qr {
                        TextField("QR destination URL", text: $payload).textFieldStyle(.roundedBorder)
                            .accessibilityIdentifier("footer.group.qrURL")
                        Text("Use a complete HTTP or HTTPS URL. example.com is a demonstration destination. QR generation and decoding happen locally.")
                            .font(.caption).foregroundStyle(.secondary).fixedSize(horizontal: false, vertical: true)
                    }
                    if !state.lastFooterContentAnnouncement.isEmpty {
                        Text(state.lastFooterContentAnnouncement).font(.callout).fixedSize(horizontal: false, vertical: true)
                            .accessibilityIdentifier("footer.group.status")
                    }
                    HStack {
                        Button("Cancel") { state.cancelFooterContent(); presenting = false }.keyboardShortcut(.cancelAction)
                        Spacer()
                        Button(state.isAddingFooterContent ? "Preparing…" : grids.isEmpty ? "Create Columns and Add" : "Add Section") {
                            state.addFooterContent(preset: preset, footerID: footer.id,
                                selectedGridID: selectedGrid, createColumnsConfirmed: grids.isEmpty, payload: payload)
                        }.keyboardShortcut(.defaultAction)
                            .disabled(state.isAddingFooterContent || (preset == .qr && !QRCodeResourceWorker.validURL(payload)) || (grids.count > 1 && selectedGrid == nil))
                            .accessibilityIdentifier("footer.group.add")
                    }
                }.padding(24).frame(width: 470)
                .onChange(of: state.footerContentCompletion) { _, _ in presenting = false }
                .onDisappear { state.cancelFooterContent() }
            }
    }
}

struct PreparedQRCodeEdit: Sendable {
    let command: DocumentCommand
    let resource: PreparedImageImport?
}

extension FooterContentWorker {
    func prepareQRUpdate(nodeID: NodeID, pageID: PageID, document: CanonicalDocument, payload: String) async throws -> PreparedQRCodeEdit {
        guard let page = document.pages.first(where: { $0.id == pageID }),
              let node = page.nodes.first(where: { $0.id == nodeID }),
              !node.selectionBooleanProperty("locked"), !node.selectionBooleanProperty("hidden"),
              let previous = try CanonicalQRCode.resolve(node) else { throw DesignInspectorError.stale }
        let prepared = try await encoder.prepare(payload: payload)
        try Task.checkCancellation()
        let existing = document.imageAssets.first { $0.contentHash == prepared.asset.contentHash }
        let asset = existing ?? prepared.asset
        var commands: [DocumentCommand] = []
        if existing == nil { commands.append(.insertImageAsset(.init(asset: asset, index: document.imageAssets.count))) }
        let values: [String: PropertyValue] = [CanonicalQRCode.namespace + "payload": .string(payload), CanonicalQRCode.namespace + "hash": .string(asset.contentHash)]
        commands += DecorativeEffectPropertyCommands.replace(namespace: CanonicalQRCode.namespace, values: values, node: node, pageID: pageID)
        func set(_ target: DocumentNode, key: String, value: PropertyValue) {
            let old = target.insertionProperty(key)
            if old?.value != value { commands.append(.setProperty(.init(pageID: pageID, nodeID: target.id,
                property: .init(id: old?.id ?? PropertyID(), key: .init(rawValue: key), value: value, origin: .authored)))) }
        }
        set(node, key: CanonicalImageStyle.namespace + "assetID", value: .string(asset.id.description))
        if node.insertionStringProperty(CanonicalImageStyle.namespace + "alt") == "QR code for " + previous.payload {
            set(node, key: CanonicalImageStyle.namespace + "alt", value: .string("QR code for " + payload))
        }
        // Ordinary adjacent links are not a second owned link model. Only a
        // still-matching destination follows regeneration; customization wins.
        let hasSingleCode = page.nodes.filter { $0.parent == node.parent && (try? CanonicalQRCode.resolve($0)) != nil }.count == 1
        for sibling in page.nodes where hasSingleCode && sibling.parent == node.parent && sibling.kind == .link {
            if (try? CanonicalLinkTarget.resolve(sibling)) == .external(previous.payload) {
                guard !sibling.selectionBooleanProperty("locked") else { throw DesignInspectorError.unavailable("Unlock the adjacent destination link before regenerating this QR code.") }
                set(sibling, key: CanonicalLinkTarget.namespace + "url", value: .string(payload))
            }
        }
        guard !commands.isEmpty else { throw DesignInspectorError.noChanges }
        let command = DocumentCommand.batch(commands)
        var draft = document; _ = try CommandRegistry().apply(command, to: &draft); try draft.validate()
        return .init(command: command, resource: existing == nil ? prepared : nil)
    }
}

struct QRCodeInspector: View {
    @ObservedObject var state: WorkspaceShellState
    let node: DocumentNode
    let code: CanonicalQRCode
    @State private var draft: String?
    var body: some View {
        VStack(alignment: .leading, spacing: 6) {
            Text("QR destination").font(.headline)
            TextField("HTTP or HTTPS URL", text: Binding(get: { draft ?? code.payload }, set: { draft = $0 }))
                .textFieldStyle(.roundedBorder).accessibilityIdentifier("inspector.qr.payload")
            Text("Generated locally with a clear quiet zone. Resize with Layout; keep the square code large enough to scan. Alt text and the adjacent link remain editable.")
                .font(.caption).foregroundStyle(.secondary).fixedSize(horizontal: false, vertical: true)
            HStack {
                Button(state.isAddingFooterContent ? "Generating…" : "Regenerate QR") {
                    state.regenerateQRCode(nodeID: node.id, payload: draft ?? code.payload)
                }.disabled(state.isAddingFooterContent || !QRCodeResourceWorker.validURL(draft ?? code.payload))
                    .accessibilityIdentifier("inspector.qr.regenerate")
                Button("Convert to Image") { state.convertQRCodeToImage(nodeID: node.id) }
                    .disabled(state.isAddingFooterContent).accessibilityIdentifier("inspector.qr.convert")
            }
            if !state.lastFooterContentAnnouncement.isEmpty { Text(state.lastFooterContentAnnouncement).font(.caption).fixedSize(horizontal: false, vertical: true) }
        }
        .onExitCommand { draft = nil; state.cancelFooterContent() }
        .onChange(of: code) { _, _ in draft = nil }
        .onDisappear { state.cancelFooterContent() }
    }
}
